import { useState, useEffect } from 'react';
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [value, setValue] = useState<T>(() => {
    const stored = localStorage.getItem(key);
    return stored ? JSON.parse(stored) : initialValue;
  });
  useEffect(() => {
    localStorage.setItem(key, JSON.stringify(value));
  }, [key, value]);
  return [value, setValue] as const;
}

import { Request, Response } from 'express';
import pdfParse from 'pdf-parse';

export interface ParsedResumeRequest extends Request {
  extractedText?: string;
}

export const handlePdfUpload = async (req: ParsedResumeRequest, res: Response): Promise<void> => {
  try {
    if (!req.file) {
      res.status(400).json({ error: 'No PDF file uploaded.' });
      return;
    }

    const pdfData = await pdfParse(req.file.buffer);
    req.extractedText = pdfData.text;

    res.status(200).json({
      success: true,
      filename: req.file.originalname,
      numpages: pdfData.numpages,
      extractedText: pdfData.text,
    });
  } catch (error: any) {
    res.status(500).json({ error: 'Failed to parse PDF file.', details: error.message });
  }
};

import { useState, useMemo } from 'react';

interface KeywordAnalysis {
  matchScore: number;
  matchedKeywords: string[];
  missingKeywords: string[];
}

export function useResumeMatch(resumeText: string, jobDescription: string) {
  const [isAnalyzing, setIsAnalyzing] = useState(false);

  const analysis = useMemo<KeywordAnalysis>(() => {
    if (!resumeText || !jobDescription) {
      return { matchScore: 0, matchedKeywords: [], missingKeywords: [] };
    }

    const cleanText = (text: string) =>
      Array.from(new Set(text.toLowerCase().match(/\b[a-z]{3,}\b/g) || []));

    const jobKeywords = cleanText(jobDescription);
    const resumeWords = new Set(cleanText(resumeText));

    const matched: string[] = [];
    const missing: string[] = [];

    jobKeywords.forEach((kw) => {
      if (resumeWords.has(kw)) {
        matched.push(kw);
      } else {
        missing.push(kw);
      }
    });

    const score = jobKeywords.length > 0 ? Math.round((matched.length / jobKeywords.length) * 100) : 0;

    return {
      matchScore: score,
      matchedKeywords: matched,
      missingKeywords: missing,
    };
  }, [resumeText, jobDescription]);

  return { ...analysis, isAnalyzing, setIsAnalyzing };
}
